mapper.select:
SELECT EXISTS (
    SELECT 1 FROM reactions r
    JOIN auth.users u ON r.users_id = u.id
    WHERE r.reference_type = CAST(#{data.referenceType} AS emoji_reference_type)
    AND r.reference_id = #{data.referenceId}
    AND r.emoji = #{data.emoji}
    AND u.email = #{email}
)

mapper.delete:
DELETE FROM reactions
WHERE reference_type = CAST(#{data.referenceType} AS emoji_reference_type)
AND reference_id = #{data.referenceId}
AND emoji = #{data.emoji}
AND users_id IN (SELECT id FROM auth.users WHERE email = #{email});
